async function saveJob(){const next=clone(current),changed=[];document.querySelectorAll('[data-job]').forEach(x=>{const key=x.dataset.job,value=x.value;if(next.job[key]!==value){next.job[key]=value;changed.push(key);}});if(!changed.length)return render();next.projectData.userEntered={...next.projectData.userEntered,objective:next.job.EXACT_USER_OBJECTIVE_VERBATIM,suppliedMaterials:next.job.SUPPLIED_MATERIALS_INVENTORY,requiredOutputFormat:next.job.REQUIRED_OUTPUT_FORMAT,deadlineOrTemporalScope:next.job.DEADLINE_OR_TEMPORAL_SCOPE,knownAuthorities:next.job.KNOWN_AUTHORITATIVE_SOURCES,availableTools:next.job.AVAILABLE_TOOLS,prohibitedActions:next.job.PROHIBITED_ACTIONS,explicitRequirements:String(next.job.EXPLICIT_USER_REQUIREMENTS||'').split(/\r?\n/).filter(Boolean)};engine.recordHumanInputVersion(next,changed,'HUMAN_OPERATOR');if(next.stages[1].status==='COMPLETE'&&!next.isRetainedTestProject){const id=engine.allocateInfrastructureId(next,'HUMAN-INPUT-CHANGE','changes');engine.invalidateDownstream(next,1,id,'User Job Input changed after Stage 01 completion.');}await persistReplacement(next);render();}
