  const plan=engine.nextPromptOperation(preview,n);if(plan.blockedReason)throw new Error(plan.blockedReason);const candidate=globalThis.closedLoopPromptEngine.buildPromptRecord(n,preview,{operation:plan.operation,scope:plan.scope}),next=clone(current),record={...candidate,generatedAt:new Date().toISOString(),iteration:current.job.CURRENT_ITERATION||'NOT APPLICABLE'};
